import React from "react";

function Header() {
    const headerStyle = {
        background: "#a82324",
        padding: "60px 24px 80px 24px",
        borderBottomLeftRadius: "40px",
        borderBottomRightRadius: "40px",
        color: "white",
        display: "flex",
        gap: "10px",
        alignItems: "center"
    };

    const infoStyle = { display: "flex", flexDirection: "column" };

    return (
        <header style={headerStyle}>
            <div className="brand-logo" style={{ width: 60, height: 60, background: "white", borderRadius: 15, padding: 5 }}></div>
            <div style={infoStyle}>
                <h1 style={{ margin: 0, fontSize: 24 }}>IITM Dashboard</h1>
                <p style={{ margin: 0, opacity: 0.9, fontSize: 14, textTransform: "uppercase", letterSpacing: 1 }}>User Name</p>
            </div>
        </header>
    );
}

export default Header;
